using System;
using System.Collections;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        // Old way: ArrayList stores object, so every int is boxed
        ArrayList old = new ArrayList();
        old.Add(10);
        old.Add("oops");               // compiles: no type safety
        Console.WriteLine("ArrayList count: " + old.Count);
        try
        {
            int sum = 0;
            foreach (object o in old) sum += (int)o;   // cast (unbox) on every read
            Console.WriteLine(sum);
        }
        catch (InvalidCastException)
        {
            Console.WriteLine("ArrayList: InvalidCastException at run time");
        }

        // Generic way: List<int> keeps raw ints, no boxing, no casts
        List<int> good = new List<int>();
        good.Add(10);
        good.Add(20);
        // good.Add("oops");           // would not compile
        int total = 0;
        foreach (int x in good) total += x;
        Console.WriteLine("List<int> total: " + total);

        // Boxing creates a separate heap object per value
        object a = 5, b = 5;
        Console.WriteLine("Two boxed 5s are the same object? " + ReferenceEquals(a, b));
    }
}

using System;
using System.Collections.Generic;

class Widget { public string Name = "default"; }

class Program
{
    // IComparable<T> constraint unlocks CompareTo inside the body
    static T Max<T>(IList<T> items) where T : IComparable<T>
    {
        T best = items[0];
        foreach (T x in items) if (x.CompareTo(best) > 0) best = x;
        return best;
    }

    // class + new(): reference type with a public parameterless constructor (new() goes last)
    static T Make<T>() where T : class, new() { return new T(); }

    // struct: non-nullable value type
    static string Kind<T>(T value) where T : struct { return typeof(T).Name + " is a value type"; }

    // where T : U (one type parameter constrains another)
    static bool Contains<T, U>(List<T> list, U probe) where T : U
    {
        foreach (T x in list) if (Equals(x, probe)) return true;
        return false;
    }

    static void Main()
    {
        Console.WriteLine("Max of ints: " + Max(new List<int> { 3, 9, 4 }));
        Console.WriteLine("Max of strings: " + Max(new List<string> { "pear", "apple", "zebra" }));
        Console.WriteLine("Made: " + Make<Widget>().Name);
        Console.WriteLine(Kind(42));
        Console.WriteLine("Contains 4: " + Contains<int, object>(new List<int> { 1, 4 }, 4));
    }
}

using System;

// A tiny chained hash table that mirrors Dictionary's buckets + entries layout
class MiniDict
{
    struct Entry { public int Hash; public int Next; public string Key; public int Value; }
    int[] buckets = new int[3];          // bucket -> index+1 of first entry (0 = empty)
    Entry[] entries = new Entry[3];
    int count;
    public int Steps;                    // chain nodes visited, to show cost

    static int Hash(string s) { int h = 17; foreach (char c in s) h = h * 31 + c; return h & 0x7fffffff; }

    public void Put(string key, int value)
    {
        if (count == entries.Length) Resize();
        int h = Hash(key), b = h % buckets.Length;
        entries[count] = new Entry { Hash = h, Next = buckets[b] - 1, Key = key, Value = value };
        buckets[b] = ++count;
    }
    void Resize()
    {
        Entry[] old = entries;
        entries = new Entry[old.Length * 2 + 1];
        buckets = new int[old.Length * 2 + 1];
        int n = count; count = 0;
        for (int i = 0; i < n; i++) Put(old[i].Key, old[i].Value);   // rehash into more buckets
    }
    public int Get(string key)
    {
        int h = Hash(key);
        for (int i = buckets[h % buckets.Length] - 1; i >= 0; i = entries[i].Next)
        {
            Steps++;
            if (entries[i].Hash == h && entries[i].Key == key) return entries[i].Value;
        }
        return -1;
    }
    public int Buckets { get { return buckets.Length; } }
}

class Program
{
    static void Main()
    {
        MiniDict d = new MiniDict();
        string[] keys = { "ann", "bob", "cy", "dee", "eve", "flo", "gus", "hal" };
        for (int i = 0; i < keys.Length; i++) d.Put(keys[i], i * 10);
        Console.WriteLine("buckets after 8 inserts: " + d.Buckets);
        foreach (string k in keys) Console.WriteLine(k + " -> " + d.Get(k));
        Console.WriteLine("missing -> " + d.Get("zed"));
        Console.WriteLine("chain steps for 9 lookups: " + d.Steps + " (about 1 each = O(1) average)");
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        int[] input = { 50, 10, 40, 20, 30 };
        Dictionary<int, string> dict = new Dictionary<int, string>();
        SortedDictionary<int, string> tree = new SortedDictionary<int, string>();
        SortedList<int, string> list = new SortedList<int, string>();
        foreach (int k in input)
        {
            dict[k] = "v" + k;       // hash table: O(1), no ordering
            tree[k] = "v" + k;       // red-black tree: O(log n)
            list[k] = "v" + k;       // sorted arrays: O(n) insert (shifts items)
        }
        Console.WriteLine("input: " + string.Join(",", input));
        Console.WriteLine("SortedDictionary keys: " + string.Join(",", tree.Keys));
        Console.WriteLine("SortedList keys:       " + string.Join(",", list.Keys));
        // SortedList supports index access; the tree does not
        Console.WriteLine("SortedList.Keys[2] = " + list.Keys[2] + ", Values[2] = " + list.Values[2]);
        Console.WriteLine("Dictionary lookup 40 = " + dict[40]);
        // Binary-search style queries on the sorted array
        int idx = list.IndexOfKey(30);
        Console.WriteLine("IndexOfKey(30) = " + idx);
        // Order only needed once at the end? sort the dictionary keys one time
        List<int> sorted = new List<int>(dict.Keys);
        sorted.Sort();
        Console.WriteLine("dictionary then one sort: " + string.Join(",", sorted));
    }
}

using System;
using System.Collections.Generic;

class LruCache
{
    class Item { public int Key; public int Value; }
    readonly int capacity;
    readonly Dictionary<int, LinkedListNode<Item>> map = new Dictionary<int, LinkedListNode<Item>>();
    readonly LinkedList<Item> order = new LinkedList<Item>();   // first = most recent
    readonly object gate = new object();                        // one lock guards both structures

    public LruCache(int capacity) { this.capacity = capacity; }

    public int Get(int key)
    {
        lock (gate)
        {
            LinkedListNode<Item> node;
            if (!map.TryGetValue(key, out node)) return -1;
            order.Remove(node);              // Remove(node) is O(1); Remove(value) would be O(n)
            order.AddFirst(node);
            return node.Value.Value;
        }
    }
    public void Put(int key, int value)
    {
        lock (gate)
        {
            LinkedListNode<Item> node;
            if (map.TryGetValue(key, out node))
            {
                node.Value.Value = value;
                order.Remove(node);
                order.AddFirst(node);
                return;
            }
            if (map.Count == capacity)
            {
                LinkedListNode<Item> last = order.Last;
                map.Remove(last.Value.Key);   // do not forget the dictionary entry
                order.RemoveLast();
            }
            map[key] = order.AddFirst(new Item { Key = key, Value = value });
        }
    }
    static void Main()
    {
        LruCache c = new LruCache(2);
        c.Put(1, 100); c.Put(2, 200);
        Console.WriteLine("get 1 = " + c.Get(1));   // 1 is now most recent
        c.Put(3, 300);                              // evicts 2
        Console.WriteLine("get 2 = " + c.Get(2));   // -1
        Console.WriteLine("get 3 = " + c.Get(3));
        Console.WriteLine("get 1 = " + c.Get(1));
    }
}

using System;
using System.Collections.Generic;

// Min-heap ordered by priority only, like PriorityQueue (mcs has no PriorityQueue, so this is a mini version)
class MiniHeap
{
    List<long[]> h = new List<long[]>();   // each item: { priority, tiebreak, id }
    bool useSeq;
    long seq;
    public MiniHeap(bool useSeq) { this.useSeq = useSeq; }
    bool Less(long[] a, long[] b)
    {
        if (a[0] != b[0]) return a[0] < b[0];
        return useSeq && a[1] < b[1];       // without a sequence number ties are arbitrary
    }
    public void Push(long id, long pri)
    {
        h.Add(new long[] { pri, seq++, id });
        int i = h.Count - 1;
        while (i > 0 && Less(h[i], h[(i - 1) / 2])) { Swap(i, (i - 1) / 2); i = (i - 1) / 2; }
    }
    public long Pop()
    {
        long id = h[0][2];
        h[0] = h[h.Count - 1]; h.RemoveAt(h.Count - 1);
        int i = 0;
        while (true)
        {
            int l = 2 * i + 1, r = l + 1, m = i;
            if (l < h.Count && Less(h[l], h[m])) m = l;
            if (r < h.Count && Less(h[r], h[m])) m = r;
            if (m == i) break;
            Swap(i, m); i = m;
        }
        return id;
    }
    public int Count { get { return h.Count; } }
    void Swap(int a, int b) { long[] t = h[a]; h[a] = h[b]; h[b] = t; }

    static void Run(bool useSeq)
    {
        MiniHeap q = new MiniHeap(useSeq);
        for (int id = 1; id <= 6; id++) q.Push(id, 5);   // six jobs, same priority
        q.Push(99, 1);
        List<long> outp = new List<long>();
        while (q.Count > 0) outp.Add(q.Pop());
        Console.WriteLine((useSeq ? "with sequence:    " : "priority only:    ") + string.Join(" ", outp));
    }
    static void Main()
    {
        Console.WriteLine("push jobs 1..6 at priority 5, then job 99 at priority 1");
        Run(false);
        Run(true);
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        List<int> nums = new List<int> { 1, 2, 3, 4, 5, 6 };
        Console.WriteLine("start: " + string.Join(",", nums));
        try
        {
            foreach (int n in nums)
                if (n % 2 == 0) nums.Remove(n);   // bumps the list's version
        }
        catch (InvalidOperationException e)
        {
            Console.WriteLine("foreach + Remove threw: " + e.GetType().Name);
        }

        nums = new List<int> { 1, 2, 3, 4, 5, 6 };
        nums.RemoveAll(n => n % 2 == 0);          // one O(n) pass
        Console.WriteLine("RemoveAll: " + string.Join(",", nums));

        nums = new List<int> { 1, 2, 3, 4, 5, 6 };
        for (int i = nums.Count - 1; i >= 0; i--) // backwards keeps unvisited indexes stable
            if (nums[i] % 2 == 0) nums.RemoveAt(i);
        Console.WriteLine("backward loop: " + string.Join(",", nums));

        List<int> src = new List<int> { 1, 2, 3, 4, 5, 6 };
        List<int> kept = new List<int>();
        foreach (int n in src) if (n % 2 != 0) kept.Add(n);   // build a new list
        Console.WriteLine("new list: " + string.Join(",", kept));
    }
}

using System;
using System.Collections.Generic;

class Person : IComparable<Person>
{
    public string Name; public int Age;
    public Person(string n, int a) { Name = n; Age = a; }
    public int CompareTo(Person o) { return string.CompareOrdinal(Name, o.Name); }  // natural order: by name
    public override string ToString() { return Name + "(" + Age + ")"; }
}
class ByAge : IComparer<Person>                       // an external, alternative order
{
    public int Compare(Person a, Person b) { return a.Age.CompareTo(b.Age); }
}
class NameIgnoreCase : IEqualityComparer<Person>      // Equals + GetHashCode for hash collections
{
    public bool Equals(Person a, Person b) { return string.Equals(a.Name, b.Name, StringComparison.OrdinalIgnoreCase); }
    public int GetHashCode(Person p) { return StringComparer.OrdinalIgnoreCase.GetHashCode(p.Name); }
}
class Program
{
    static void Main()
    {
        List<Person> ps = new List<Person> { new Person("Cara", 30), new Person("ann", 21), new Person("Bob", 25) };
        ps.Sort();
        Console.WriteLine("IComparable (name):  " + string.Join(" ", ps));
        ps.Sort(new ByAge());
        Console.WriteLine("IComparer (age):     " + string.Join(" ", ps));
        HashSet<Person> set = new HashSet<Person>(new NameIgnoreCase());
        set.Add(new Person("Bob", 25));
        bool added = set.Add(new Person("BOB", 99));
        Console.WriteLine("IEqualityComparer: BOB added again? " + added + ", set size " + set.Count);
    }
}

