using System;
using System.Collections.Generic;

// C# 7 stand-in for generic math (INumber<T> needs C# 11): a struct "calculator" that supplies the operations
interface IMath<T> { T Zero { get; } T Add(T a, T b); }
struct IntMath : IMath<int> { public int Zero { get { return 0; } } public int Add(int a, int b) { return a + b; } }
struct DoubleMath : IMath<double> { public double Zero { get { return 0.0; } } public double Add(double a, double b) { return a + b; } }
struct LongMath : IMath<long> { public long Zero { get { return 0L; } } public long Add(long a, long b) { return a + b; } }

class Program
{
    // One generic algorithm; struct M is specialised by the JIT, so calls inline and nothing is boxed
    static T Sum<T, M>(IList<T> xs) where M : struct, IMath<T>
    {
        M m = default(M);
        T total = m.Zero;
        foreach (T x in xs) total = m.Add(total, x);
        return total;
    }
    static void Main()
    {
        Console.WriteLine("ints:    " + Sum<int, IntMath>(new List<int> { 1, 2, 3, 4 }));
        Console.WriteLine("doubles: " + Sum<double, DoubleMath>(new List<double> { 0.5, 1.25, 2.0 }));
        Console.WriteLine("longs:   " + Sum<long, LongMath>(new List<long> { 3000000000L, 4000000000L }));
        // With .NET 7+ the same would be: T Sum<T>(IEnumerable<T> xs) where T : INumber<T>
    }
}

using System;
using System.Collections;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        List<int> list = new List<int> { 1, 2, 3 };
        Console.WriteLine("List<int>.Enumerator is a struct: " + typeof(List<int>.Enumerator).IsValueType);

        // Typed as List<int>: struct enumerator, lives on the stack
        List<int>.Enumerator direct = list.GetEnumerator();
        // Typed as IEnumerable<int>: the struct is boxed into a heap object
        IEnumerator<int> boxed1 = ((IEnumerable<int>)list).GetEnumerator();
        IEnumerator<int> boxed2 = ((IEnumerable<int>)list).GetEnumerator();
        Console.WriteLine("two interface enumerators are different objects: " + !ReferenceEquals(boxed1, boxed2));

        // A mutable struct enumerator is copied on assignment; the boxed one is shared by reference
        boxed1.MoveNext();
        IEnumerator<int> alias = boxed1;
        alias.MoveNext();
        Console.WriteLine("boxed1.Current after alias moved: " + boxed1.Current);   // 2, shared

        List<int>.Enumerator copy = direct;
        direct.MoveNext();
        copy.MoveNext(); copy.MoveNext();
        Console.WriteLine("direct.Current = " + direct.Current + ", copy.Current = " + copy.Current);  // independent
        int sum = 0;
        foreach (int x in list) sum += x;             // pattern-based: no allocation
        Console.WriteLine("sum = " + sum);
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        // 100,000 distinct keys, built once and never changed (FrozenSet needs .NET 8, so compare the classic options)
        List<string> words = new List<string>();
        for (int i = 0; i < 100000; i++) words.Add("key-" + (i * 7919 % 100000));
        HashSet<string> set = new HashSet<string>(words, StringComparer.Ordinal);   // O(1) lookup
        string[] sorted = words.ToArray();
        Array.Sort(sorted, StringComparer.Ordinal);                                // binary search: O(log n), least memory

        string[] probes = { "key-0", "key-99999", "key-100000", "KEY-5", "nope" };
        foreach (string p in probes)
        {
            bool inSet = set.Contains(p);
            bool inArr = Array.BinarySearch(sorted, p, StringComparer.Ordinal) >= 0;
            Console.WriteLine(p + ": hashset=" + inSet + " sortedArray=" + inArr);
        }
        Console.WriteLine("size: " + set.Count + " distinct keys");
        Console.WriteLine("ordinal vs ignore-case: " + new HashSet<string>(words, StringComparer.OrdinalIgnoreCase).Contains("KEY-5"));
    }
}

using System;
using System.Collections.Generic;

struct BadKey            // default struct hashing is slow/poor; here Equals is counted and the hash is bad
{
    public int Tenant, Id;
    public static int EqualsCalls;
    public BadKey(int t, int i) { Tenant = t; Id = i; }
    public override int GetHashCode() { return Tenant; }               // all keys of a tenant collide
    public override bool Equals(object o) { EqualsCalls++; BadKey k = (BadKey)o; return k.Tenant == Tenant && k.Id == Id; }
}
struct GoodKey
{
    public int Tenant, Id;
    public static int EqualsCalls;
    public GoodKey(int t, int i) { Tenant = t; Id = i; }
    public override int GetHashCode() { return unchecked(Tenant * 31 + Id); }   // uses every field
    public override bool Equals(object o) { EqualsCalls++; GoodKey k = (GoodKey)o; return k.Tenant == Tenant && k.Id == Id; }
}
class Program
{
    static void Main()
    {
        Dictionary<BadKey, int> bad = new Dictionary<BadKey, int>();
        Dictionary<GoodKey, int> good = new Dictionary<GoodKey, int>();
        for (int i = 0; i < 2000; i++) { bad[new BadKey(1, i)] = i; good[new GoodKey(1, i)] = i; }
        BadKey.EqualsCalls = 0; GoodKey.EqualsCalls = 0;
        for (int i = 0; i < 2000; i++) { int a = bad[new BadKey(1, i)]; int b = good[new GoodKey(1, i)]; }
        Console.WriteLine("2000 lookups, one tenant");
        Console.WriteLine("bad hash  Equals calls: " + BadKey.EqualsCalls);
        Console.WriteLine("good hash Equals calls: " + GoodKey.EqualsCalls);
        // Diagnosis tip: count distinct hash codes
        HashSet<int> hs = new HashSet<int>();
        for (int i = 0; i < 2000; i++) hs.Add(new BadKey(1, i).GetHashCode());
        Console.WriteLine("distinct hashes among 2000 bad keys: " + hs.Count);
    }
}

using System;
using System.Collections.Generic;

class Order { public long Id; public int Qty; public Order(long id, int q) { Id = id; Qty = q; } }
class Desc : IComparer<long> { public int Compare(long a, long b) { return b.CompareTo(a); } }

class Book
{
    public SortedDictionary<long, LinkedList<Order>> Asks = new SortedDictionary<long, LinkedList<Order>>();
    public SortedDictionary<long, LinkedList<Order>> Bids = new SortedDictionary<long, LinkedList<Order>>(new Desc());
    Dictionary<long, LinkedListNode<Order>> byId = new Dictionary<long, LinkedListNode<Order>>();

    public void Add(SortedDictionary<long, LinkedList<Order>> side, long price, Order o)
    {
        LinkedList<Order> level;
        if (!side.TryGetValue(price, out level)) { level = new LinkedList<Order>(); side[price] = level; }
        byId[o.Id] = level.AddLast(o);                 // FIFO within a price level
    }
    static long Best(SortedDictionary<long, LinkedList<Order>> s)
    {
        foreach (long k in s.Keys) return k;           // first key = best price
        return -1;
    }
    public void Match(long buyPrice, int qty)
    {
        while (qty > 0 && Asks.Count > 0 && Best(Asks) <= buyPrice)
        {
            long p = Best(Asks);
            LinkedList<Order> lvl = Asks[p];
            Order o = lvl.First.Value;
            int fill = Math.Min(qty, o.Qty);
            o.Qty -= fill; qty -= fill;
            Console.WriteLine("fill " + fill + " @ " + p + " vs order " + o.Id);
            if (o.Qty == 0) { lvl.RemoveFirst(); byId.Remove(o.Id); }
            if (lvl.Count == 0) Asks.Remove(p);        // drop empty price levels
        }
        Console.WriteLine("unfilled: " + qty);
    }
    public void Cancel(long id, SortedDictionary<long, LinkedList<Order>> side, long price)
    {
        LinkedListNode<Order> n = byId[id];
        side[price].Remove(n); byId.Remove(id);        // O(1) removal from the middle
    }
    static void Main()
    {
        Book b = new Book();
        b.Add(b.Asks, 10100, new Order(1, 5));   // prices in integer ticks
        b.Add(b.Asks, 10050, new Order(2, 3));
        b.Add(b.Asks, 10050, new Order(3, 4));
        b.Add(b.Bids, 9990, new Order(4, 2));
        b.Add(b.Bids, 10000, new Order(5, 2));
        Console.WriteLine("best ask " + Best(b.Asks) + ", best bid " + Best(b.Bids));
        b.Cancel(3, b.Asks, 10050);
        b.Match(10100, 7);
    }
}
